 37	const MARKER_PREFIX = 'bestsellers-update';
 38	const MARKER_TTL_SECONDS = 7 * 24 * 60 * 60;
 39	const TRANSIENT_ATTEMPTS = 3;
 40	const TRANSIENT_BACKOFF_MS = 100;
