 42	// Errors that retrying can clear (the SDK's own retry has already tried, so a second
 43	// bounded pass here is what "don't swallow a conflict" asks for).
 44	const TRANSIENT_ERRORS = new Set([
 45	  'ThrottlingException',
 46	  'ProvisionedThroughputExceededException',
 47	  'TransactionInProgressException',
 48	  'TransactionConflictException',
 49	  'InternalServerError',
 50	  'ServiceUnavailable',
 51	  'RequestTimeout',
 52	  'RequestThrottled',
 53	]);
