 55	function isTransient(err) {
 56	  if (!err) return false;
 57	  if (err.name === 'ConditionalCheckFailedException') return false;
 58	  if (TRANSIENT_ERRORS.has(err.name)) return true;
 59	  // Transport failures reach us as TypeError/TimeoutError/socket errors.
 60	  return err.$metadata && err.$metadata.httpStatusCode >= 500;
 61	}
