 67	/**
 68	 * (a) Claim this (orderId, index). True when this delivery is the first one that got
 69	 * here, false when an earlier delivery already applied the element.
 70	 */
 71	async function claimElement(orderId, index, bookId) {
 72	  const params = {
 73	    TableName: idempotencyTable,
 74	    Item: {
 75	      pk: `${MARKER_PREFIX}#${orderId}#${index}`,
 76	      orderId: orderId,
 77	      bookId: bookId,
 78	      createdAt: Date.now(),
 79	      expiresAt: Math.floor(Date.now() / 1000) + MARKER_TTL_SECONDS
 80	    },
 81	    ConditionExpression: 'attribute_not_exists(pk)'
 82	  };
 83	
 84	  try {
 85	    await docClient.send(new PutCommand(params));
 86	    return true;
 87	  } catch (error) {
 88	    if (error.name === 'ConditionalCheckFailedException') return false;
 89	    throw error;
 90	  }
 91	}
