 94	 * (b) The counter update, utils/bestsellers.js:17-26 verbatim: ADD on the key, no
 95	 * ConditionExpression, so the first sale creates the row.
 96	 */
 97	async function addSalesCount(bookId, quantity) {
 98	  const params = {
 99	    TableName: bestsellersTable,
100	    Key: { bookId: bookId },
101	    UpdateExpression: 'ADD salesCount :qty',
102	    ExpressionAttributeValues: {
103	      ':qty': quantity
104	    }
105	  };
106	
107	  await docClient.send(new UpdateCommand(params));
108	}
