110	async function withTransientRetry(operation, what) {
111	  let lastError = null;
112	  for (let attempt = 1; attempt <= TRANSIENT_ATTEMPTS; attempt++) {
113	    try {
114	      return await operation();
115	    } catch (error) {
116	      lastError = error;
117	      if (!isTransient(error)) throw error;
118	      if (attempt < TRANSIENT_ATTEMPTS) {
119	        console.warn(`Retrying ${what} (attempt ${attempt}):`, error.message);
120	        await sleep(TRANSIENT_BACKOFF_MS * attempt);
121	      }
122	    }
123	  }
124	  throw lastError;
125	}
