165	      } catch (error) {
166	        if (isTransient(error)) {
167	          // Still failing after the bounded retries: hand it back so SQS redelivers.
168	          console.error('Transient failure updating bestseller:', error);
169	          const identifier = { itemIdentifier: record.messageId };
170	          if (!batchItemFailures.some((f) => f.itemIdentifier === identifier.itemIdentifier)) {
171	            batchItemFailures.push(identifier);
172	          }
173	        } else {
174	          // Permanent, e.g. ValidationException on a string quantity: the monolith's
175	          // updateBestSeller caught it and returned false (BR-ORD-CRT-9/14).
176	          console.error('Failed to update bestseller:', error);
177	        }
178	      }
179	    }
180	  }
181	
182	  // ReportBatchItemFailures: only the listed messages are redelivered; an empty list
183	  // means the whole batch is done.
184	  return { batchItemFailures };
185	};

