    const { bookId, quantity } = body;

    // Truthiness only (BR-CART-UPD-1): quantity 0 is "missing"; price is ignored.
    if (!bookId || !quantity) {
      return respond(400, {
        error: 'Missing required fields: bookId, quantity'
      });
    }

    const params = {
      TableName: cartTable,
      Key: {
        customerId: customerIdOf(event),
        bookId: bookId
