      UpdateExpression: 'SET quantity = :quantity',
      ExpressionAttributeValues: {
        ':quantity': quantity
      },
      ReturnValues: 'ALL_NEW'
    };

    // No ConditionExpression: an entry that is not there is created with the key and
    // the new quantity only, and the answer is still 200 (BR-CART-UPD-3/4, SI-24).
    await docClient.send(new UpdateCommand(params));
    return respond(200, { message: 'Cart updated successfully' });
  } catch (error) {
    console.error('Error in PUT /cart:', error);
    return respondError(error);
  }
