// [R4] The items one message will read or write ("table|key"), computed with the same
// builders the loop body uses; [] when the message is skipped before any DynamoDB
// call. The claimed marker is part of the list: two deliveries of the same
// (orderId, index) share it and must never be applied side by side.
function recordItemKeys(record) {
  let payload;
  try {
    payload = JSON.parse(record.body);
  } catch (error) {
    return [];
  }
  const orderId = payload && payload.orderId;
  const books = payload && payload.books;
  if (!orderId || !Array.isArray(books)) return [];
  const keys = [];
  for (let index = 0; index < books.length; index++) {
    const bookId = books[index] && books[index].bookId;
    keys.push(`${idempotencyTable}|${JSON.stringify({ pk: markerKey(orderId, index) })}`);
    keys.push(`${bestsellersTable}|${JSON.stringify(salesKey(bookId))}`);
  }
  return keys;
}

// [R4] A message goes one wave after the latest earlier message it shares an item
// with: messages of one wave touch disjoint items, and every item still sees the
// messages in batch order.
function scheduleWaves(records, keysOf) {
  const lastWave = new Map();
  const waves = [];
  for (const record of records) {
    const keys = keysOf(record);
    let wave = 0;
    for (const key of keys) if (lastWave.has(key)) wave = Math.max(wave, lastWave.get(key) + 1);
    for (const key of keys) lastWave.set(key, wave);
    (waves[wave] = waves[wave] || []).push(record);
  }
  return waves;
}

