// [R1/R4] The items one element of a message touches ("table|key"), built with the
// same key builders the loop bodies use: the marker the element claims, and the
// bestseller row it adds to. Two deliveries of the same (orderId, index) share the
// marker, and two elements naming the same book share the row.
function elementKeys(orderId, index, book) {
  const bookId = book && book.bookId;
  return [
    `${idempotencyTable}|${JSON.stringify({ pk: markerKey(orderId, index) })}`,
    `${bestsellersTable}|${JSON.stringify(salesKey(bookId))}`,
  ];
}

// [R4] The items one message will read or write, computed with the same builders the
// loop body uses; [] when the message is skipped before any DynamoDB call.
function recordItemKeys(record) {
  let payload;
  try {
    payload = JSON.parse(record.body);
  } catch (error) {
    return [];
  }
  const orderId = payload && payload.orderId;
  const books = payload && payload.books;
  if (!orderId || !Array.isArray(books)) return [];
  const keys = [];
  for (let index = 0; index < books.length; index++) keys.push(...elementKeys(orderId, index, books[index]));
  return keys;
}

// [R4] A work item goes one wave after the latest earlier item that shares one of its
// items with it: the items of one wave touch disjoint rows, and every row still sees
// the items in their original order.
function scheduleWaves(items, keysOf) {
  const lastWave = new Map();
  const waves = [];
  for (const item of items) {
    const keys = keysOf(item);
    let wave = 0;
    for (const key of keys) if (lastWave.has(key)) wave = Math.max(wave, lastWave.get(key) + 1);
    for (const key of keys) lastWave.set(key, wave);
    (waves[wave] = waves[wave] || []).push(item);
  }
  return waves;
}

